    ap = next((p for p in after['projects'] if p['path'].split('/')[-1] == proj), None)
    if not ap: continue
    for bf in bp['frameworks']:
        fw = bf['framework']
        af = next((f for f in ap['frameworks'] if f['framework'] == fw), None)
        if not af: continue
        b_pkgs = {p['id']: p['resolvedVersion'] for p in bf['topLevelPackages']}
        a_pkgs = {p['id']: p['resolvedVersion'] for p in af['topLevelPackages']}
        for pkg in sorted(set(list(b_pkgs.keys()) + list(a_pkgs.keys()))):
            bv = b_pkgs.get(pkg, 'N/A')
            av = a_pkgs.get(pkg, 'N/A')
            if bv != av:
                changes.append((proj, fw, pkg, bv, av))
            else:
                unchanged.append((proj, fw, pkg, bv))

print('=== CHANGES ===')
if changes:
    for c in changes:
        print(f'{c[0]} ({c[1]}): {c[2]} {c[3]} -> {c[4]}')
else:
    print('None')
print(f'\n=== UNCHANGED: {len(unchanged)} packages ===')"
